let output = '';
for (let i = 1; i <= 5; i++) {
  output += i + ' ';
}
document.getElementById('loopForResult').textContent = output;

let total = 0;
let i = 1;
do {
  total += i;
  i++;
} while (total < 10);
document.getElementById('loopDoWhileResult').textContent = total;

const fruits = ['Apple', 'Banana', 'Cherry'];
let output = '';
for (const fruit of fruits) {
  output += fruit + ' ';
}
document.getElementById('loopForOfResult').textContent = output;

const person = { name: 'Alex', age: 25, city: 'Miami' };
let output = '';
for (const key in person) {
  output += key + ' ';
}
document.getElementById('loopForInResult').textContent = output;
